TITLE='SentinelTrace An Explainable Local Log Based Threat Triage and Alert Prioritization System'

def setup(d):
 s=d.sections[0]; s.page_width=Inches(8.27); s.page_height=Inches(11.69); s.left_margin=Inches(1.5); s.right_margin=Inches(1); s.top_margin=Inches(1); s.bottom_margin=Inches(1)
 st=d.styles['Normal']; st.font.name='Times New Roman'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman'); st.font.size=Pt(11); st.paragraph_format.line_spacing=1.5
 for n,size in [('Title',18),('Heading 1',15),('Heading 2',13),('Heading 3',11)]:
  x=d.styles[n]; x.font.name='Times New Roman'; x.font.size=Pt(size); x.font.bold=True; x.font.color.rgb=None
 header=s.header.paragraphs[0]; header.alignment=WD_ALIGN_PARAGRAPH.CENTER; header.add_run('SENTINELTRACE  |  FOURTH YEAR MINI PROJECT').font.size=Pt(9)
 footer=s.footer.paragraphs[0]; footer.alignment=WD_ALIGN_PARAGRAPH.CENTER; footer.add_run('Department of Computer Science and Engineering  |  ').font.size=Pt(9)
 fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); footer._p.append(fld)
def para(d,t='',bold=False):
 p=d.add_paragraph(); r=p.add_run(t); r.bold=bold; return p
def table(d, heads, rows):
 t=d.add_table(rows=1, cols=len(heads)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
 for c,h in zip(t.rows[0].cells,heads): c.text=h; c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
 for row in rows:
  cells=t.add_row().cells
  for c,v in zip(cells,row): c.text=str(v); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
 return t
def page(d, heading, paragraphs, tbl=None, page_break=False):
 if page_break and len(d.paragraphs)>1: d.add_page_break()
 d.add_heading(heading,1)
 for x in paragraphs: para(d,x)
 if tbl: table(d,*tbl)
