 p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.space_after=Pt(18)
 r=p.add_run('LLOYD INSTITUTE OF ENGINEERING AND TECHNOLOGY'); r.bold=True; r.font.size=Pt(16)
 p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run('Department of Computer Science and Engineering').bold=True
